  const target=colorTarget();bar.hidden=target.kind==="canvas";if(bar.hidden)return;
  const set=(id,show,value,hex)=>{const wrap=$(id+"Wrap");if(wrap)wrap.hidden=!show;const input=$(id+"Color");if(input)input.value=validColor(value,"#526fff");const label=$(id+"Hex");if(label)label.textContent=validColor(value,"#526fff").toUpperCase();if(show&&hex&&!target.supports[state.quickColorKind])state.quickColorKind=hex};
