async function syncGoogleDrive(){
  if(!state.accessToken){await signInGoogle();if(!state.accessToken)return}
  try{
    const headers={Authorization:`Bearer ${state.accessToken}`},name="BriefCraft AI.workspace.json",query=encodeURIComponent(`name='${name}' and trashed=false`);
    const listResponse=await fetch(`https://www.googleapis.com/drive/v3/files?q=${query}&fields=files(id,name,modifiedTime)&spaces=drive`,{headers});
    if(!listResponse.ok)throw new Error(`Drive list HTTP ${listResponse.status}`);
    const found=await listResponse.json();let id=found.files?.[0]?.id,remote=null;
    if(id){const download=await fetch(`https://www.googleapis.com/drive/v3/files/${id}?alt=media`,{headers});if(download.ok){try{remote=await download.json()}catch{remote=null}}}
    const remoteProjects=Array.isArray(remote?.projects)?remote.projects:[],localProjects=Array.isArray(state.projects)?state.projects:[],merged=new Map();
    for(const p of [...remoteProjects,...localProjects]){if(!p?.id)continue;const prev=merged.get(p.id);if(!prev||Number(p.updated||0)>=Number(prev.updated||0))merged.set(p.id,p)}
    state.projects=[...merged.values()];
    if(!state.projects.some(p=>p.id===state.activeProject))state.activeProject=remote?.activeProject&&state.projects.some(p=>p.id===remote.activeProject)?remote.activeProject:(state.projects[0]?.id||null);
    const payload=JSON.stringify({format:"briefcraft-workspace-v3",projects:state.projects,activeProject:state.activeProject,theme:state.theme,language:state.language,syncedAt:Date.now()});
    if(!id){const create=await fetch("https://www.googleapis.com/drive/v3/files",{method:"POST",headers:{...headers,"Content-Type":"application/json"},body:JSON.stringify({name,mimeType:"application/json"})});if(!create.ok)throw new Error(`Drive create HTTP ${create.status}`);id=(await create.json()).id}
    const upload=await fetch(`https://www.googleapis.com/upload/drive/v3/files/${id}?uploadType=media`,{method:"PATCH",headers:{...headers,"Content-Type":"application/json"},body:payload});
    if(!upload.ok)throw new Error(`Drive upload HTTP ${upload.status}`);
    await persist();renderProjectGrid();if(state.activeProject)renderAll(true);showToast(state.language==="ru"?"Проекты синхронизированы с Google Drive":"Projects synced with Google Drive");logChange(tr("syncReady"))
  }catch(error){console.warn("BriefCraft Drive sync",error);showToast(`${tr("syncFailed")}: ${error?.message||error}`)}
}

