/* 3.8.50 — theme-aware object colors and shared control contrast. */
function bcLuminance50(value){const c=validColor(value,"");if(!c)return null;const rgb=[1,3,5].map(i=>parseInt(c.slice(i,i+2),16)/255).map(v=>v<=.04045?v/12.92:Math.pow((v+.055)/1.055,2.4));return .2126*rgb[0]+.7152*rgb[1]+.0722*rgb[2]}
function bcReadableText50(background){const l=bcLuminance50(background);return l!==null&&l>.42?"#171a22":"#f3f5fa"}
function bcObjectFillColor50(obj){if(obj?.themeSurface&&obj.fillMode!=="custom")return state.theme==="dark"?"#20252e":"#ffffff";return validColor(obj?.fill,state.theme==="dark"?"#20252e":"#ffffff")}
function bcObjectTextColor50(obj){if(obj?.themeSurface&&obj._bcThemeText50!==false)return obj.fillMode==="custom"?bcReadableText50(bcObjectFillColor50(obj)):(state.theme==="dark"?"#f3f5fa":"#171a22");return validColor(obj?.textColor,bcReadableText50(bcObjectFillColor50(obj)))}
function bcSyncColorInputs50(root=document){root.querySelectorAll?.('input[type="color"]').forEach(input=>{input.style.setProperty("--bc-color-value",validColor(input.value,"#526fff"));input.dataset.bcColorReady="1"})}
(()=>{const migrate=()=>{let changed=false;for(const p of state.projects||[])for(const obj of p.objects||[]){if(obj?.themeSurface&&obj._bcThemeText50===undefined){obj._bcThemeText50=true;changed=true}}if(changed)queuePersist()};migrate();bcSyncColorInputs50();document.addEventListener("input",e=>{if(e.target?.matches?.('input[type="color"]'))bcSyncColorInputs50(e.target.parentElement||document)},true);new MutationObserver(records=>{for(const record of records)for(const node of record.addedNodes)if(node.nodeType===1)bcSyncColorInputs50(node)}).observe(document.documentElement,{childList:true,subtree:true});applyTheme();renderColorBar();renderInspector()})();

