/* 3.8.50 — readable controls in both themes and Google setup. */
input,textarea,select,.field input,.field textarea,.field select,.quick-color,.paint-mode>label{color:var(--text)}
input::placeholder,textarea::placeholder{color:var(--muted);opacity:1}
input[type="color"]{border:1px solid color-mix(in srgb,var(--text) 24%,var(--line))!important;border-radius:7px!important;background:repeating-conic-gradient(#d9dde7 0 25%,#fff 0 50%) 50%/10px 10px!important;overflow:hidden}
input[type="color"]::-webkit-color-swatch-wrapper{padding:2px}input[type="color"]::-webkit-color-swatch{border:1px solid color-mix(in srgb,var(--text) 30%,transparent);border-radius:5px}
html[data-theme="light"] .canvas-object{--object-text-fallback:#171a22}html[data-theme="dark"] .canvas-object{--object-text-fallback:#f3f5fa}
.quick-color b,.paint-mode label span,.canvas-color-input b{color:var(--text)!important;opacity:.86}
.bc-google-setup50{position:fixed;z-index:5000;inset:0;display:grid;place-items:center;padding:20px;background:rgba(5,8,14,.62);backdrop-filter:blur(10px)}.bc-google-setup50[hidden]{display:none}
.bc-google-card50{width:min(620px,calc(100vw - 30px));max-height:calc(100vh - 34px);overflow:auto;border:1px solid var(--line);border-radius:22px;background:var(--surface);color:var(--text);box-shadow:var(--shadow)}
.bc-google-card50 header{height:70px;padding:0 18px 0 22px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line)}.bc-google-card50 header small,.bc-google-card50 header strong{display:block}.bc-google-card50 header small{color:var(--muted);font-size:9px;letter-spacing:.12em}.bc-google-card50 header strong{margin-top:4px;font-size:18px}.bc-google-card50 header button{width:38px;height:38px;border:1px solid var(--line);border-radius:12px;background:var(--surface-2);font-size:24px}
.bc-google-card50 section{margin:14px;padding:16px;border:1px solid var(--line);border-radius:16px;background:var(--surface-2)}.bc-google-card50 section>b{font-size:14px}.bc-google-card50 section p{margin:7px 0 12px;color:var(--muted);font-size:12px;line-height:1.5}.bc-google-card50 section a{display:inline-block;margin-top:10px;color:var(--accent);font-size:11px}.bc-google-card50 section em{display:block;margin-top:9px;color:var(--green);font-style:normal;font-size:11px}
.bc-google-row50{display:grid;grid-template-columns:1fr auto;gap:8px}.bc-google-row50 input{min-width:0;height:42px;padding:0 12px;border:1px solid var(--line);border-radius:11px;background:var(--surface)}.bc-google-row50 button,.bc-google-actions50 button{height:42px;padding:0 14px;border:1px solid var(--line);border-radius:11px;background:var(--surface);font-weight:700}.bc-google-row50 button{border:0;color:#fff;background:linear-gradient(120deg,var(--accent),var(--accent-2))}.bc-google-actions50{display:flex;gap:8px;flex-wrap:wrap}
@media(max-width:620px){.bc-google-row50{grid-template-columns:1fr}.bc-google-row50 button{width:100%}}
